def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]

    # Check all possible starting positions for prefix in s
    for i in range(len(s) - len(prefix) + 1):
        if s[i:i + len(prefix)] == prefix:
            # Check all possible ending positions for suffix in s
            for j in range(i + len(prefix), len(s) + 1):
                if s[j - len(suffix):j] == suffix:
                    return True
    return False

