def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse from left to right
            for j in range(0, len(grid[i]), 2):
                result.append(grid[i][j])
        else:
            # Traverse from right to left
            for j in range(len(grid[i]) - 1, -1, -2):
                result.append(grid[i][j])
    return result

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            if counts[s[i]] == int(s[i]) and counts[s[i + 1]] == int(s[i + 1]):
                return s[i] + s[i + 1]
    return ""

