def maxDifference(s: str) -> int:
    from collections import Counter
    frequencies = Counter(s)
    odd_max = -1
    even_max = -1
    for freq in frequencies.values():
        if freq % 2 == 0:
            even_max = max(even_max, freq)
        else:
            odd_max = max(odd_max, freq)
    return odd_max - even_max if odd_max != -1 and even_max != -1 else 0

