def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]

    # Initialize the first house costs
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the dp array for all houses
    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i - 1][(j + 1) % 3], dp[i - 1][(j + 2) % 3])

    # Account for equidistant constraints
    for i in range(n // 2):
        for j in range(3):
            for k in range(3):
                if k != j:  # No adjacent and equidistant houses can have the same color
                    dp[n - 1 - i][k] = min(dp[n - 1 - i][k], dp[i][j] + cost[n - 1 - i][k])

    return min(dp[n - 1][j] for j in range(3))

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers
    events.sort(key=lambda x: int(x[1]))  # Sort events by timestamp
    for event in events:
        event_type, timestamp, *details = event
        timestamp = int(timestamp)
        # Process offline status before handling messages
        for i in range(numberOfUsers):
            if not online_status[i] and timestamp >= offline_until[i]:
                online_status[i] = True
        if event_type == "MESSAGE":
            mentions_string = details[0]
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                for mention in mentions_string.split():
                    user_id = int(mention[2:])
                    mentions[user_id] += 1
        elif event_type == "OFFLINE":
            user_id = int(details[0])
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60
    return mentions

