def maxDistance(s: str, k: int) -> int:
    # Initial position
    x, y = 0, 0
    # Track the maximum distance
    max_dist = 0
    # Count movements
    for char in s:
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1
        # Calculate current Manhattan distance
        current_dist = abs(x) + abs(y)
        # Update maximum distance considering k changes
        max_dist = max(max_dist, current_dist + min(k, (len(s) - s.index(char) - 1)) * 2)
    return max_dist
